  /**
   * ZK input buffer containing cryptographic data for the claim.
   * Contains: rescue encryption data, Groth16 proof, merkle root, timestamps, fees.
   * Closed after processing to return rent to relayer.
   */
  claimInputBuffer: Address<TAccountClaimInputBuffer>;
  /** Used as a seed for deriving the user and token account PDAs. */
  receiverAddress: Address<TAccountReceiverAddress>;
