export function parseDepositFromPublicBalanceIntoExistingNetworkBalanceV11CallbackInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedDepositFromPublicBalanceIntoExistingNetworkBalanceV11CallbackInstruction<
  TProgram,
  TAccountMetas
> {
  if (instruction.accounts.length < 16) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      arciumProgram: getNextAccount(),
      compDefAccount: getNextAccount(),
      mxeAccount: getNextAccount(),
      computationAccount: getNextAccount(),
      clusterAccount: getNextAccount(),
      instructionsSysvar: getNextAccount(),
      depositor: getNextAccount(),
      depositorSplAta: getNextAccount(),
      receiverAddress: getNextAccount(),
      receiverTokenAccount: getNextAccount(),
      feeVault: getNextAccount(),
      tokenPool: getNextAccount(),
      tokenPoolSplAta: getNextAccount(),
      mint: getNextAccount(),
      tokenProgram: getNextAccount(),
      computationData: getNextAccount(),
    },
    data: getDepositFromPublicBalanceIntoExistingNetworkBalanceV11CallbackInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
