export type ParsedReencryptNetworkGrantForSharedBalanceV11Instruction<
  TProgram extends string = typeof UMBRA_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    receiver: TAccountMetas[0];
    /** The fee payer who pays rent for account creation. */
    feePayer: TAccountMetas[1];
    signPdaAccount: TAccountMetas[2];
    mxeAccount: TAccountMetas[3];
    mempoolAccount: TAccountMetas[4];
    executingPool: TAccountMetas[5];
    computationAccount: TAccountMetas[6];
    compDefAccount: TAccountMetas[7];
    clusterAccount: TAccountMetas[8];
    poolAccount: TAccountMetas[9];
    clockAccount: TAccountMetas[10];
    systemProgram: TAccountMetas[11];
    arciumProgram: TAccountMetas[12];
    /**
     * The network shared compliance grant proving receiver has permission.
     * PDA seeds: [SEED, granter_x25519, nonce, receiver_x25519]
     */
    viewingGrant: TAccountMetas[13];
    /** Program information for priority fees. */
    protocolConfig: TAccountMetas[14];
    /**
     * MPC callback data account - stores all data needed by the callback handler.
     * Initialized here and closed in the callback (rent returned to receiver).
     */
    computationData: TAccountMetas[15];
  };
  data: ReencryptNetworkGrantForSharedBalanceV11InstructionData;
};

export function parseReencryptNetworkGrantForSharedBalanceV11Instruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedReencryptNetworkGrantForSharedBalanceV11Instruction<
  TProgram,
  TAccountMetas
> {
  if (instruction.accounts.length < 16) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      receiver: getNextAccount(),
      feePayer: getNextAccount(),
      signPdaAccount: getNextAccount(),
      mxeAccount: getNextAccount(),
      mempoolAccount: getNextAccount(),
      executingPool: getNextAccount(),
      computationAccount: getNextAccount(),
      compDefAccount: getNextAccount(),
      clusterAccount: getNextAccount(),
      poolAccount: getNextAccount(),
      clockAccount: getNextAccount(),
      systemProgram: getNextAccount(),
      arciumProgram: getNextAccount(),
      viewingGrant: getNextAccount(),
      protocolConfig: getNextAccount(),
      computationData: getNextAccount(),
    },
    data: getReencryptNetworkGrantForSharedBalanceV11InstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
